#!/bin/bash
# Script para verificar la versión real y proporcionar comandos para forzar actualización en el navegador

echo "==========================================="
echo "🔍 Verificando Versión Real vs Navegador"
echo "==========================================="
echo ""

CONTAINER_ID=$(docker ps --filter "name=dashboard" --format "{{.ID}}" | head -1)

if [ -z "$CONTAINER_ID" ]; then
    echo "❌ No se encontró contenedor del dashboard"
    exit 1
fi

echo "Contenedor: $CONTAINER_ID"
echo ""

# 1. Verificar versión en el contenedor
echo "1️⃣ Versión REAL en el contenedor:"
echo ""

BUILD_TS=$(docker exec "$CONTAINER_ID" grep -oP "window\.BUILD_TIMESTAMP\s*=\s*['\"][^'\"]*['\"]" /app/dashboard.html 2>/dev/null | head -1)
VERSION=$(docker exec "$CONTAINER_ID" grep -oP "window\.DASHBOARD_VERSION\s*=\s*['\"][^'\"]*['\"]" /app/dashboard.html 2>/dev/null | head -1)

if [ -n "$BUILD_TS" ]; then
    echo "   ✅ $BUILD_TS"
else
    echo "   ❌ No se encontró BUILD_TIMESTAMP"
fi

if [ -n "$VERSION" ]; then
    echo "   ✅ $VERSION"
else
    echo "   ❌ No se encontró DASHBOARD_VERSION"
fi

echo ""

# 2. Verificar qué está sirviendo el servidor
echo "2️⃣ Verificando qué está sirviendo el servidor..."
echo ""

HTTP_STATUS=$(docker exec "$CONTAINER_ID" node -e "
const http = require('http');
http.get('http://127.0.0.1:3000/', {family: 4}, (res) => {
    let data = '';
    res.on('data', (chunk) => { data += chunk; });
    res.on('end', () => {
        const buildMatch = data.match(/window\.BUILD_TIMESTAMP\s*=\s*['\"]([^'\"]+)['\"]/);
        const versionMatch = data.match(/window\.DASHBOARD_VERSION\s*=\s*['\"]([^'\"]+)['\"]/);
        console.log('Status:', res.statusCode);
        if (buildMatch) console.log('BUILD_TIMESTAMP:', buildMatch[1]);
        if (versionMatch) console.log('DASHBOARD_VERSION:', versionMatch[1]);
        process.exit(0);
    });
}).on('error', (err) => {
    console.log('ERROR:', err.message);
    process.exit(1);
});
" 2>/dev/null)

echo "$HTTP_STATUS"
echo ""

# 3. Verificar headers del servidor
echo "3️⃣ Verificando headers del servidor..."
echo ""

HEADERS=$(docker exec "$CONTAINER_ID" node -e "
const http = require('http');
http.get('http://127.0.0.1:3000/', {family: 4}, (res) => {
    console.log('Cache-Control:', res.headers['cache-control'] || 'NO ENCONTRADO');
    console.log('Pragma:', res.headers['pragma'] || 'NO ENCONTRADO');
    console.log('Expires:', res.headers['expires'] || 'NO ENCONTRADO');
    console.log('X-Build-Timestamp:', res.headers['x-build-timestamp'] || 'NO ENCONTRADO');
    process.exit(0);
}).on('error', (err) => {
    console.log('ERROR:', err.message);
    process.exit(1);
});
" 2>/dev/null)

echo "$HEADERS" | sed 's/^/   /'
echo ""

# 4. Instrucciones para el navegador
echo "==========================================="
echo "🌐 SOLUCIÓN: Forzar Actualización en Navegador"
echo "==========================================="
echo ""
echo "El contenedor tiene la versión CORRECTA, pero el navegador está usando caché."
echo ""
echo "Ejecuta estos comandos en la CONSOLA del navegador (F12):"
